struct RestoreLimit {
  int& target;
  int saved;
  bool active = true;

  ~RestoreLimit() {
    if (active) target = saved;
  }

  void commit() { active = false; }
};

bool try_limit(int& limit, int proposed) {
  RestoreLimit guard{limit, limit};
  limit = proposed;
  if (limit < 1 || limit > 100) {
    return false;
  }
  return true;
}
